import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ═══════════════════════════════════════════════════════════════════
  // 1. ROOT GROUP & CLEANUP REGISTRY
  // ═══════════════════════════════════════════════════════════════════
  const root = new THREE.Group();
  root.position.set(3.2, 1, 0.06);
  root.rotation.order = 'XYZ';

  const timelines = [];
  const resources = [];

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    resources.forEach((res) => {
      if (res.dispose) res.dispose();
    });
  };

  // ═══════════════════════════════════════════════════════════════════
  // 2. PLANE GEOMETRY & MATERIAL
  // ═══════════════════════════════════════════════════════════════════
  const planeGeom = new THREE.PlaneGeometry(1.2, 0.75);
  resources.push(planeGeom);

  // Load the image texture
  const imagePlane = new THREE.Mesh(
    planeGeom,
    new MeshBasicNodeMaterial({ color: 0xffffff })
  );
  resources.push(imagePlane.material);

  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    texture.colorSpace = THREE.SRGBColorSpace;
    imagePlane.material.colorNode = uv();
    imagePlane.material.map = texture;
    imagePlane.material.needsUpdate = true;
  });

  root.add(imagePlane);

  // ═══════════════════════════════════════════════════════════════════
  // 3. TEXT: "Collection 3" (headline)
  // ═══════════════════════════════════════════════════════════════════
  const textObject = ctx.fontAtlas.createText('Collection 3', {
    fontSize: 39,
    color: '#e8ecf2',
    align: 'center',
  });
  textObject.position.z = 0.1;
  textObject.position.y = -0.15;
  root.add(textObject);

  // ═══════════════════════════════════════════════════════════════════
  // 4. STATIC COMPOSITION: NO INTERACTIVITY
  // ═══════════════════════════════════════════════════════════════════
  // This is a static card label — no cinematic primitives applied,
  // no event handlers. The plane and text are rendered as a static
  // composition within the collection section.

  return root;
}
